/// <summary>
/// NDX_MultipleSelect_Quotation
/// </summary>
class NDX_MultipleSelect_Quotation extends NDX_MultipleSelect
{
    NDXMultipleS_SalesQuotation nDX_SelectionTmp;        // Vorlagedaten für die Selektion der bereits markierten Datensätze
    QuotationIdBase             quotationId;
    SalesQuotationTable         salesQuotationTable;
}

Method.Source:
void closedSelectForm()
{
    FormDataSource  formDatasource;
    int             i, nBis;
    tableId         tableId;

    nBis = selectForm.dataSourceCount();
    for (i = 1; i <= nBis; i++)
    {
        formDataSource  = selectForm.dataSource(i);
        tableId         = formDataSource.table();
        if (tableId == tablenum(NDXMultipleS_SalesQuotation))
        {
            nDX_SelectionTmp.data(formDatasource.cursor());
            break;
        }
    }
}

/// <summary>
/// Gets all all valid quotations ids for an item
/// </summary>
/// <param name = "_inventTable">item record</param>
/// <returns>String of quotation ids</returns>
static public str Range2String(InventTable _inventTable)
{
    #define.Comma(' ,')

    NDXMultipleS_SalesQuotation       nDX_MultipleS_Quotation;
    SalesQuotationTable lSalesQuotationTable;

    str range2String;
    boolean             lFirst = true;
    ;

    while select nDX_MultipleS_Quotation
        where nDX_MultipleS_Quotation.RefRecId_InventTable == _inventTable.RecId
        join lSalesQuotationTable
            where lSalesQuotationTable.RecId == nDX_MultipleS_Quotation.RefRecId_SalesQuotationTable
    {
        if (!lFirst)
        {
            range2String += #Comma;
        }
        else
        {
            lFirst = false;
        }

        range2String += lSalesQuotationTable.QuotationId;
    }
    return range2String;
}
